<script setup>
import { onMounted, ref } from 'vue'
import loyaltyApi from '@/api/loyalty.api'
import { getApiErrorMessage } from '@/api/error'
const tiers=ref([]),rules=ref([]),error=ref(''),tier=ref({name:'',min_spend:0,min_orders:0,priority:0,benefits:{}}),rule=ref({name:'',rule_type:'spend',spend_amount:10000,points:1,rounding:'floor',priority:0,stackable:true,is_active:true})
async function load(){try{[tiers.value,rules.value]=await Promise.all([loyaltyApi.tiers(),loyaltyApi.rules()])}catch(e){error.value=getApiErrorMessage(e)}}
async function addTier(){try{await loyaltyApi.createTier(tier.value);tier.value={name:'',min_spend:0,min_orders:0,priority:0,benefits:{}};await load()}catch(e){error.value=getApiErrorMessage(e)}}
async function addRule(){try{await loyaltyApi.createRule(rule.value);rule.value={name:'',rule_type:'spend',spend_amount:10000,points:1,rounding:'floor',priority:0,stackable:true,is_active:true};await load()}catch(e){error.value=getApiErrorMessage(e)}}
onMounted(load)
</script>
<template><div class="loyalty-page"><header class="loyalty-header"><div><h1>تنظیمات باشگاه</h1><p>سطوح عضویت و قوانین واقعی امتیازدهی</p></div></header><p v-if="error" class="loyalty-error">{{error}}</p><div class="loyalty-grid-2"><section class="loyalty-card"><h2>سطوح عضویت</h2><table class="loyalty-table"><thead><tr><th>نام</th><th>حداقل خرید</th><th>سفارش</th></tr></thead><tbody><tr v-for="x in tiers" :key="x.id"><td>{{x.name}}</td><td>{{Number(x.min_spend).toLocaleString('fa-IR')}}</td><td>{{x.min_orders}}</td></tr><tr v-if="!tiers.length"><td colspan="3" class="loyalty-empty">هنوز سطح عضویتی تعریف نشده است.</td></tr></tbody></table><form class="loyalty-form" @submit.prevent="addTier"><label>نام<input v-model="tier.name" required></label><label>حداقل خرید<input v-model.number="tier.min_spend" type="number" min="0"></label><label>حداقل سفارش<input v-model.number="tier.min_orders" type="number" min="0"></label><button class="admin-button admin-button--primary">افزودن سطح</button></form></section><section class="loyalty-card"><h2>قوانین امتیاز</h2><table class="loyalty-table"><thead><tr><th>نام</th><th>نوع</th><th>امتیاز</th><th>مبنای خرید</th></tr></thead><tbody><tr v-for="x in rules" :key="x.id"><td>{{x.name}}</td><td>{{x.rule_type==='spend'?'خرید':'اولین خرید'}}</td><td>{{x.points}}</td><td>{{x.spend_amount||'—'}}</td></tr><tr v-if="!rules.length"><td colspan="4" class="loyalty-empty">هنوز قانونی تعریف نشده است.</td></tr></tbody></table><form class="loyalty-form" @submit.prevent="addRule"><label>نام<input v-model="rule.name" required></label><label>نوع<select v-model="rule.rule_type"><option value="spend">امتیاز خرید</option><option value="first_purchase">هدیه اولین خرید</option></select></label><label v-if="rule.rule_type==='spend'">به ازای مبلغ<input v-model.number="rule.spend_amount" type="number" min="1"></label><label>امتیاز<input v-model.number="rule.points" type="number" min="1" required></label><button class="admin-button admin-button--primary">افزودن قانون</button></form></section></div></div></template>
